window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3cdf2e0a952fa965"]={"versions": [{"id": "FIG-3cdf2e0a952fa965", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Basismuster-Anforderungen (<code>ServiceNeeds</code>) von Software-Komponenten an die Basessoftware (BSW) im AUTOSAR-Metamodell der Software Component Template. Es zeigt die Generalisierungshierarchie ausgehend vom abstrakten Basiselement <code>ServiceNeeds</code> (spezialisiert von <code>Identifiable</code>) hin zu domänenspezifischen Service-Bedarfsklassen für NVRAM-Manager, Watchdog-/Supervision-Manager, Communication-Manager und ECU-State-Manager inklusive zugehöriger Enumerationstypen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>ServiceNeeds</code>: Abstrakte Basisklasse, erbt von <code>Identifiable</code>.</li>\n<li><code>NvBlockNeeds</code>: Spezialisiert <code>ServiceNeeds</code>. Enthält Attribute:</li>\n<li><code>+ nDataSets: Int</code></li>\n<li><code>+ readonly: Boolean</code></li>\n<li><code>+ reliability: NvBlockNeedsReliabilityEnum</code></li>\n<li><code>+ resistantToChangedSw: Boolean</code></li>\n<li><code>+ restoreAtStart: Boolean</code></li>\n<li><code>+ writeOnlyOnce: Boolean</code></li>\n<li><code>+ writingFrequency: Int</code></li>\n<li><code>+ writingPriority: NvBlockNeedsWritingPriorityEnum</code></li>\n<li><code>SupervisedEntityNeeds</code>: Spezialisiert <code>ServiceNeeds</code>. Enthält Attribute:</li>\n<li><code>+ activateAtStart: Boolean</code></li>\n<li><code>+ enableDeactivation: Boolean</code></li>\n<li><code>+ expectedAliveCycle: Float</code></li>\n<li><code>+ maxAliveCycle: Float</code></li>\n<li><code>+ minAliveCycle: Float</code></li>\n<li><code>+ toleratedFailedCycles: Int</code></li>\n<li><code>ComMgrUserNeeds</code>: Spezialisiert <code>ServiceNeeds</code>. Enthält Attribut:</li>\n<li><code>+ maxCommMode: MaxCommModeEnum</code></li>\n<li><code>EcuStateMgrUserNeeds</code>: Spezialisiert <code>ServiceNeeds</code> ohne eigene Attribute.</li>\n<li><code>«enumeration» NvBlockNeedsReliabilityEnum</code>: Literale <code>low</code>, <code>medium</code>, <code>high</code>.</li>\n<li><code>«enumeration» NvBlockNeedsWritingPriorityEnum</code>: Literale <code>low</code>, <code>medium</code>, <code>high</code>.</li>\n<li><code>«enumeration» MaxCommModeEnum</code>: Literale <code>none</code>, <code>silent</code>, <code>full</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne Sequenzen oder dynamische Interaktionsflüsse. Die modellierten Klassen dienen als deklarative Konfigurationsbeschreibungen zur Entwurfs- und Generierungszeit, über welche Software-Komponenten ihre Laufzeit- und BSW-Dienstanforderungen an den BSW-Stack formulieren.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klassen und Enumerationen definieren verbindliche Metamodell-Elemente für die Formalisierung des Dienstbedarfs (Service Needs) von AUTOSAR-Softwarekomponenten. Werkzeuge zur Generierung der BSW-Konfiguration (z. B. NvM, WdgM, ComM, EcuM) werten diese Attribute aus, um Kanäle, Kontrollblöcke, Prioritäten und zyklische Prüfparameter im BSW- und RTE-Stack deterministisch zu konfigurieren.</p>"}, {"id": "FIG-f13f8d778339a59b", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Basismuster-Anforderungen (<code>ServiceNeeds</code>) von Software-Komponenten an die Basessoftware (BSW) im AUTOSAR-Metamodell der Software Component Template. Es zeigt die Generalisierungshierarchie ausgehend vom abstrakten Basiselement <code>ServiceNeeds</code> (spezialisiert von <code>Identifiable</code>) hin zu domänenspezifischen Service-Bedarfsklassen für NVRAM-Manager, Watchdog-/Supervision-Manager, Communication-Manager und ECU-State-Manager inklusive zugehöriger Enumerationstypen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>ServiceNeeds</code>: Abstrakte Basisklasse, erbt von <code>Identifiable</code>.</li>\n<li><code>NvBlockNeeds</code>: Spezialisiert <code>ServiceNeeds</code>. Enthält Attribute:</li>\n<li><code>+ nDataSets :Integer</code></li>\n<li><code>+ ramBlockStatusControl :RamBlockStatusControlEnum [0..1]</code></li>\n<li><code>+ readonly :Boolean</code></li>\n<li><code>+ reliability :NvBlockNeedsReliabilityEnum</code></li>\n<li><code>+ resistantToChangedSw :Boolean</code></li>\n<li><code>+ restoreAtStart :Boolean</code></li>\n<li><code>+ storeAtShutdown :Boolean [0..1]</code></li>\n<li><code>+ writeOnlyOnce :Boolean</code></li>\n<li><code>+ writingFrequency :Integer</code></li>\n<li><code>+ writingPriority :NvBlockNeedsWritingPriorityEnum</code></li>\n<li><code>SupervisedEntityNeeds</code>: Spezialisiert <code>ServiceNeeds</code>. Enthält Attribute:</li>\n<li><code>+ activateAtStart :Boolean</code></li>\n<li><code>+ enableDeactivation :Boolean</code></li>\n<li><code>+ expectedAliveCycle :Float</code></li>\n<li><code>+ maxAliveCycle :Float</code></li>\n<li><code>+ minAliveCycle :Float</code></li>\n<li><code>+ toleratedFailedCycles :Integer</code></li>\n<li><code>ComMgrUserNeeds</code>: Spezialisiert <code>ServiceNeeds</code>. Enthält Attribut:</li>\n<li><code>+ maxCommMode :MaxCommModeEnum</code></li>\n<li><code>EcuStateMgrUserNeeds</code>: Spezialisiert <code>ServiceNeeds</code> ohne eigene Attribute.</li>\n<li><code>«enumeration» NvBlockNeedsReliabilityEnum</code>: Literale <code>low</code>, <code>medium</code>, <code>high</code>.</li>\n<li><code>«enumeration» NvBlockNeedsWritingPriorityEnum</code>: Literale <code>low</code>, <code>medium</code>, <code>high</code>.</li>\n<li><code>«enumeration» RamBlockStatusControlEnum</code>: Literale <code>api</code>, <code>nvRamManager</code>.</li>\n<li><code>«enumeration» MaxCommModeEnum</code>: Literale <code>none</code>, <code>silent</code>, <code>full</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne Sequenzen oder dynamische Interaktionsflüsse. Die modellierten Klassen dienen als deklarative Konfigurationsbeschreibungen zur Entwurfs- und Generierungszeit, über welche Software-Komponenten ihre Laufzeit- und BSW-Dienstanforderungen an den BSW-Stack formulieren.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klassen und Enumerationen definieren verbindliche Metamodell-Elemente für die Formalisierung des Dienstbedarfs (Service Needs) von AUTOSAR-Softwarekomponenten. Werkzeuge zur Generierung der BSW-Konfiguration (z. B. NvM, WdgM, ComM, EcuM) werten diese Attribute aus, um Kanäle, Kontrollblöcke, Prioritäten und zyklische Prüfparameter im BSW- und RTE-Stack deterministisch zu konfigurieren.</p>"}], "trans": [{"from": "FIG-3cdf2e0a952fa965", "to": "FIG-f13f8d778339a59b", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>NvBlockNeeds</code>: Neues optionales Attribut <code>ramBlockStatusControl: RamBlockStatusControlEnum [0..1]</code> eingefügt.</li>\n<li><code>NvBlockNeeds</code>: Neues optionales Attribut <code>storeAtShutdown: Boolean [0..1]</code> eingefügt.</li>\n<li><code>NvBlockNeeds</code>: Typ der Attribute <code>nDataSets</code> und <code>writingFrequency</code> von <code>Int</code> zu <code>Integer</code> geändert.</li>\n<li><code>SupervisedEntityNeeds</code>: Typ des Attributs <code>toleratedFailedCycles</code> von <code>Int</code> zu <code>Integer</code> geändert.</li>\n<li>Neues Enumeration-Element <code>«enumeration» RamBlockStatusControlEnum</code> mit den Literalen <code>api</code> und <code>nvRamManager</code> ergänzt.</li>\n</ul>"}]};
